settings.custom_css:
selector {
  position: fixed !important;
  bottom: 24px !important;
  left: 50% !important;
  transform: translate(-50%, 40px);
  z-index: 999 !important;
  max-width: 720px;
  width: calc(100% - 32px);
  border-radius: 50px;
  background-color: #18181B;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  opacity: 0;
  pointer-events: none;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box;
}
selector.is-visible {
  opacity: 1 !important;
  pointer-events: auto !important;
  transform: translate(-50%, 0) !important;
}
@media (max-width: 767px) {
  selector {
    bottom: 16px !important;
    width: 90% !important;
    padding: 8px 12px !important;
  }
}

selector a {
  background-color: #00C853;
  transition: all 0.2s ease;
}
selector a:hover {
  background-color: #059669;
}
@media (max-width: 767px) {
  selector a {
    padding: 10px 16px;
    font-size: 13px;
  }
}

selector { max-width: 1320px; margin: 0 auto; width: 100%; box-sizing: border-box; background-color: #FCF9F2; border: 1px solid #F5E8C7; border-radius: 32px; font-family: 'Open Sans', sans-serif; }
selector .des-badge-pill { white-space: nowrap; }
@media (max-width: 767px) {
  selector { padding: 24px 16px !important; border-radius: 24px !important; }
}
